      &lt;div class=&quot;dialog-content&quot;&gt;
        &lt;v-card&gt;welcome to dialog&lt;/v-card&gt;
      &lt;/div&gt;
    &lt;/v-dialog&gt;
  &lt;/div&gt;
&lt;/template&gt;

&lt;script setup&gt;
import {ref} from &quot;vue&quot;;

const dialog = ref(false);
&lt;/script&gt;
</code></pre>
<p>and here is a <strong>unit test</strong> for it:</p>
<pre><code>import '../setup';
