    if err != nil {
        panic(err)
    }
    defer res.Body.Close()
    for _, cookie := range res.Cookies() {
        req.AddCookie(cookie)
    }


    cookies := req.Cookies()
    for i := 0; i &lt; len(cookies); i++ {
        for j := i + 1; j &lt; len(cookies); j++ {
