                    CommandParameter=&quot;{Binding .}&quot;/&gt;
            &lt;/DataTemplate&gt;
        &lt;/ItemsControl.ItemTemplate&gt;
    &lt;/ItemsControl&gt;
&lt;/UserControl&gt;
</code></pre>
<p><code>MyUserControl</code> code behind:</p>
<pre><code>public partial class MyUserControl : UserControl
{
    public static readonly DirectProperty&lt;MyItemsControl, ReactiveCommand&lt;SomeItem, Unit&gt;&gt; RemoveThisItemCommandProperty =
        AvaloniaProperty.RegisterDirect&lt;MyItemsControl, ReactiveCommand&lt;SomeItem, Unit&gt;&gt;(nameof(RemoveThisItemCommand), x =&gt; x. RemoveThisItemCommand, (x, v) =&gt; x.RemoveThisItemCommand = v);

    private ReactiveCommand&lt;SomeItem, Unit&gt; _removeThisItemCommand;
    public ReactiveCommand&lt;SomeItem, Unit&gt; RemoveThisItemCommand
    {
        get =&gt; _removeThisItemCommand;
        set =&gt; SetAndRaise(RemoveThisItemCommandProperty, ref _removeThisItemCommand, value);
    }
}
</code></pre>
<p>Code compiles fine, and displays <code>MyView</code> and <code>MyUserControl</code> as expected, but nothing happens when I click a button which is generated by ItemTemplate.</p>
<p>I also tried declaring RemoveThisItemCommandProperty as a StyledProperty, and tried using ICommand instead of ReactiveCommand in <code>MyUserControl</code> code behind. But nothing works.</p>
<p>If I use ICommand instead of ReactiveCommand, and bind from xaml in <code>MyView</code> instead of constructor it works as expected and parameter is passed through to command:</p>
<pre><code>&lt;mycontrols:MyItemsControl
        Name=&quot;MyItemsControl1&quot;
        RemoveThisItemCommand=&quot;{Binding RemoveItemCommand}&quot;&gt;
</code></pre>
<p>But I wanted to bind in constructor, since it is recommended to do so by <a href="https://www.reactiveui.net/docs/handbook/data-binding/avalonia" rel="nofollow noreferrer">documentation here</a>. Is there a way to bind this button command with parameter in view constructor?</p>

