xmlns:cor=&quot;http://acme.com/&quot;&gt;
   &lt;soapenv:Header/&gt;
   &lt;soapenv:Body&gt;
      &lt;cor:copyTool&gt;
       &lt;toolNumber&gt;some Text instead of Integer&lt;/toolNumber&gt;
      &lt;/cor:copyTool&gt;
   &lt;/soapenv:Body&gt;
