Title: Defining initial coordinates for nodes with children in a D3JS animation.
Body: <p>I have SVG nodes that I defined as <code>&lt;g&gt;</code> elements that contain one <code>&lt;circle&gt;</code> and one <code>&lt;text&gt;</code> inside them.</p>
<p>Here's an examples HTML:</p>
<pre><code>&lt;g class=&quot;nodes&quot;&gt;
    &lt;g&gt;
        &lt;circle r=&quot;63&quot;&gt;&lt;/circle&gt;
        &lt;text class=&quot;true&quot;&gt;Croatia&lt;/text&gt;
    &lt;/g&gt;
(...)
</code></pre>
<p>I am animating them in d3js (v6) as to achieve a circular packing effect, using forces. All is working well, I just am not at all able to define the initial coordinates for my elements. The elements starting position is top right, and I would like them to be in the center of my SVG area when the animation starts.</p>
<p>I have tried giving my node <code>&lt;g&gt;</code> elements &quot;x, y&quot; attributes, as well as <code>transform: translate</code> them before the animation starts, to no avail.</p>
<p>I also tried initializing each object &quot;x&quot; and &quot;y&quot; values, before turning them into nodes, as so:</p>
<pre><code>arrayOfCountries.forEach((country) =&gt; {
    country[&quot;x&quot;] = 300;
    country[&quot;y&quot;] = 700;
});

var simulation = d3
  .forceSimulation()
  //add nodes
  .nodes(arrayOfCountries);
</code></pre>
<p>I have created an animations with:</p>
<pre><code>simulation.on(&quot;tick&quot;, tickActions);
</code></pre>
<p>and animated it using:</p>
<pre><code>function tickActions() {
    //update g transform:
    node.attr(&quot;transform&quot;, function (d) {
      return &quot;translate(&quot; + [d.x, d.y] + &quot;)&quot;;
    });
}
</code></pre>
<p>Any idea how I could make sure the nodes start animating from center outwards?</p>
<p>Here's an outline of my code (I'm using Vue JS 3):</p>
<pre><code>renderCountries() {
  // #graph3 is my main SVG
  var svg = d3.select(&quot;#graph3&quot;);

  // Clear the previous map, if any
  svg.selectAll(&quot;*&quot;).remove();
  // create somewhere to put the force directed graph
  let width = +svg.attr(&quot;width&quot;);
  let height = +svg.attr(&quot;height&quot;);

  let arrayOfCountries = this.euCountryList.values;

  arrayOfCountries.forEach((country) =&gt; {
    country[&quot;x&quot;] = 300;
    country[&quot;y&quot;] = 700;
  });

 var simulation = d3
   .forceSimulation()
   //add nodes
   .nodes(arrayOfCountries);

   // add forces
   // we're going to add a charge to each node
   // also going to add a centering force
   simulation
     .force(&quot;charge_force&quot;, d3.forceManyBody().strength(-200))
     .force(&quot;center_force&quot;, d3.forceCenter(width / 2, height / 2))
     .force(
       &quot;x&quot;,
       d3
         .forceX()
         .x(function (d) {
         let lon = parseFloat(d[2].replace(&quot;,&quot;, &quot;.&quot;).replace(&quot; &quot;, &quot;&quot;));
         // shift 20 units so as to avoid negative numbers
         let displayLon = (lon + 20) * 22;
              return displayLon;
            })
            .strength(5)
        )
        .force(
          &quot;y&quot;,
          d3
            .forceY()
            .y(function (d) {
              let lat = parseFloat(d[1].replace(&quot;,&quot;, &quot;.&quot;).replace(&quot; &quot;, &quot;&quot;));
              let displayLat = height - lat * 10;
              // console.log(&quot;LAT: &quot; + displayLat);
              return displayLat;
            })
            .strength(5)
        )
        .force(
          &quot;collide&quot;,
          d3
            .forceCollide()
            .strength(0.01)
            .radius(function (d) {
              if (d[14]) {
                let radius = parseFloat(
                  d[14].replace(&quot;,&quot;, &quot;.&quot;).replace(&quot; &quot;, &quot;&quot;)
                );
                return radius;
              } else {
                return 50;
              }
            })
            .iterations(35)
        ); // Force that avoids circle overlapping;

      // add tick instructions
      simulation.on(&quot;tick&quot;, tickActions);

(...)

// draw circles
var node = svg
  .append(&quot;g&quot;)
  .attr(&quot;class&quot;, &quot;nodes&quot;)
  .selectAll(&quot;circle&quot;)
  .data(arrayOfCountries)
  .enter()
  .append(&quot;g&quot;);

var circles = node
  .append(&quot;circle&quot;)
  .attr(&quot;r&quot;, function (d) {
    if (d[14]) {
      let radius = parseFloat(d[14].replace(&quot;,&quot;, &quot;.&quot;).replace(&quot; &quot;, &quot;&quot;));
      // Bail if radius is Not A Number; possibly a presedential election in a monarchy, eg, Spain.
      if (isNaN(radius)) {
        return 0;
      }
      if (radius &gt; 35) {
        return radius / 1.1;
      } else {
        // define a minimum radius
        return 35;
      }
      // No data for abstention in country. Hide country in map.
    } else {
