struct ContentView3: View {
    /// List of words
    @State var words: [Word] = [
        Word(id: 0, front: &quot;Spanish&quot;, back: &quot;English&quot;, term: &quot;to speak&quot;, definition: &quot;hablar&quot;, accuracy: 63, wordclass: &quot;Verb&quot;),
