                                        // Remove that user from our array
                                        self.words.removeAll { $0.id == removedWord.id }
                                    })
                                    .animation(.spring())
                                    .frame(width: self.getCardWidth(geometry, id: word.id), height: 400)
                                    .offset(x: 0, y: self.getCardOffset(geometry, id: word.id))
                                }
                            }
                        }
                    }
                    Spacer()
                }
            }
        }.padding()
