//MARK: CardView
struct CardView: View {
    @State private var translation: CGSize = .zero
    @State private var swipeStatus: LikeDislike = .none

    @State var backDegree = 0.0
    @State var frontDegree = -90.0
    @State var isFlipped = true

    let durationAndDelay : CGFloat = 0.3

    var word: Word
    private var onRemove: (_ word: Word) -&gt; Void

    private var thresholdPercentage: CGFloat = 0.5 // when the user has draged 50% the width of the screen in either direction

    private enum LikeDislike: Int {
        case like, dislike, none
    }

    init(word: Word, onRemove: @escaping (_ word: Word) -&gt; Void) {
        self.word = word
        self.onRemove = onRemove
    }

    private func getGesturePercentage(_ geometry: GeometryProxy, from gesture: DragGesture.Value) -&gt; CGFloat {
        gesture.translation.width / geometry.size.width
    }

    func flipCard () {
        isFlipped = !isFlipped
        if isFlipped {
            withAnimation(.linear(duration: durationAndDelay)) {
                backDegree = 90
            }
            withAnimation(.linear(duration: durationAndDelay).delay(durationAndDelay)){
                frontDegree = 0
            }
        } else {
            withAnimation(.linear(duration: durationAndDelay)) {
                frontDegree = -90
            }
            withAnimation(.linear(duration: durationAndDelay).delay(durationAndDelay)){
                backDegree = 0
            }
        }
    }

    var body: some View {
        GeometryReader { geometry in
            VStack(alignment: .leading) {
                ZStack(alignment: self.swipeStatus == .like ? .topLeading : .topTrailing) {
                    if self.swipeStatus == .like {
                        Text(&quot;YES&quot;)
                            .font(.headline)
                            .padding()
                            .cornerRadius(10)
                            .foregroundColor(Color.green)
                            .overlay(
                                RoundedRectangle(cornerRadius: 10)
                                    .stroke(Color.green, lineWidth: 3.0)
                            ).padding(24)
                            .rotationEffect(Angle.degrees(-45))
                    } else if self.swipeStatus == .dislike {
                        Text(&quot;NO&quot;)
                            .font(.headline)
                            .padding()
                            .cornerRadius(10)
                            .foregroundColor(Color.red)
                            .overlay(
                                RoundedRectangle(cornerRadius: 10)
                                    .stroke(Color.red, lineWidth: 3.0)
                            ).padding(.top, 45)
                            .rotationEffect(Angle.degrees(45))
                    }
                    ZStack {
                        CardFront2(word: word, degree: $frontDegree)
                        CardBack2(word: word, degree: $backDegree)
                    }.onTapGesture {
                        flipCard ()
                    }
                }
            }
            .animation(.interactiveSpring())
            .offset(x: self.translation.width, y: 0)
            .rotationEffect(.degrees(Double(self.translation.width / geometry.size.width) * 1), anchor: .bottom)
            .gesture(
                DragGesture()
                    .onChanged { value in
                        self.translation = value.translation

                        if (self.getGesturePercentage(geometry, from: value)) &gt;= self.thresholdPercentage {
                            self.swipeStatus = .like
                        } else if self.getGesturePercentage(geometry, from: value) &lt;= -self.thresholdPercentage {
                            self.swipeStatus = .dislike
                        } else {
                            self.swipeStatus = .none
                        }

                    }.onEnded { value in
                        // determine snap distance &gt; 0.5 (half the width of the screen)
                        if abs(self.getGesturePercentage(geometry, from: value)) &gt; self.thresholdPercentage {
                            self.onRemove(self.word)
                        } else {
                            self.translation = .zero
                        }
                    }
            )
        }
    }
}

