Title: Click on an object using canvas and javascript.
Body: <p>I created a canvas with a circle inside it and I'm trying to detect the mouse click.</p>
<p>I am calculating the distance between the mouse click and the radius of the circle. The output should be <code>0</code> when the click is next to the center of the circle however I'm getting more than <code>400</code>!</p>
<p>Here is the code that I have tried. I couldn't understand what I'm doing wrong!?</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let canvas = document.querySelector('canvas');
let ctx = canvas.getContext('2d');
let mousePos = {
  x: undefined,
  y: undefined
};

function Circle(x, y, r) {
  this.x = x;
  this.y = y;
  this.r = r;

  this.draw = function() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2, false);
    ctx.stroke();
    ctx.fill();
    ctx.closePath();
  };

  this.clickCircle = function(xmouse, ymouse) {
    let distance = Math.sqrt(
      (xmouse - this.x) * (xmouse - this.x) +
      (ymouse - this.y) * (ymouse - this.y)
    );
    console.log(distance);
  };
}

let myCircle = new Circle(100, 100, 20);
myCircle.draw();

canvas.addEventListener('click', e =&gt; {
  const rect = canvas.getBoundingClientRect();
  mousePos.x = e.clientX - rect.left;
  mousePos.y = e.clientY - rect.top;

  myCircle.clickCircle(mousePos.x, mousePos.y);
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>canvas {
  border: 1px solid black;
  background-color: wheat;
  width: 100%;
}</code></pre>
