modifier = Modifier
    .fillMaxWidth()
    .padding(horizontal = 32.dp, vertical = 16.dp)
    .drawBehind {
        drawRoundRect(
            color = Color.Blue,
            size = Size(size.width, size.height),
            style = Stroke(
                width = 3f, pathEffect = PathEffect.dashPathEffect(
