}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://code.jquery.com/jquery-3.7.0.min.js"&gt;&lt;/script&gt;

&lt;div class="gallery-container"&gt;
  &lt;div class="scrollable-area"&gt;
    &lt;div class="gallery-items"&gt;
