            )//scale
        }//v
    }//body

    let revenueDataRule: [RevenueRule] = [
        RevenueRule(period: &quot;2022 Q1&quot;, band: &quot;Sales&quot;, high: 162, low: 105),
        RevenueRule(period: &quot;2022 Q1&quot;, band: &quot;IT&quot;, high: 105, low: 70),
        RevenueRule(period: &quot;2022 Q1&quot;, band: &quot;Finance&quot;, high: 70, low: 35),
        RevenueRule(period: &quot;2022 Q1&quot;, band: &quot;CEO&quot;, high: 35, low: 1),
        RevenueRule(period: &quot;2022 Q1&quot;, band: &quot;Intern&quot;, high: 0, low: -10)
        ]
}

struct RevenueRule: Identifiable {
    let id = UUID()
    let period: String
    let band: String
    let high: Double
    let low: Double
}
