gcc -lpthread -I/usr/include -O0 -g3 -Wall -c -fmessage-length=0 -MMD -MP -MF&quot;src/main.d&quot; -MT&quot;src/main.o&quot; -o &quot;src/main.o&quot; &quot;../src/main.c&quot;
Invoking: GCC C Linker
