Title: Playwright &#39;Re-use state&#39; &amp; &#39;Re-use Authentication&#39; with Firebase.
Body: <p>I'm trying to make sure that in each test that runs, I don't have to log in to the platform I'm testing. To achieve this, I'm implementing 'Re-use state' &amp; 'Re-use Authentication'. However, Firebase uses indexedDB instead of Cookies or SessionStorage. StorageState does not persist the indexedDB here. Maybe you know a solution for this?</p>
<p>global-setup.ts:</p>
<pre><code>import { Browser, chromium, expect, Page } from &quot;@playwright/test&quot;;

async function globalSetup(){
  const browser = await chromium.launch({headless: false});
  const context = await browser.newContext();
  const page: Page = await context.newPage();
  await page.goto(&quot;&lt;'url'&gt;&quot;)
  await page.getByLabel('Email').fill('&lt;'email'&gt;');
  await page.getByLabel('Password').fill('&lt;'password'&gt;');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect (page.getByRole('link', { name: 'logo' })).toBeVisible({ timeout: 30000 });

  //save state
  await page.context().storageState({ path: &quot;./LoginAuth.json&quot; });

  await browser.close();
}

export default globalSetup;
</code></pre>
