    Student line;

    std::fstream bitwise(&quot;D:\\cpp\\mid_product.txt&quot;, std::ios::app);
    std::ofstream result(&quot;D:\\cpp\\result.txt&quot;, std::ios::app);



    for (int i = 0; i &lt; students_count; i++) {

        file &gt;&gt; line.faculty &gt;&gt; line.course &gt;&gt; line.group;
