Title: variadic function in golang.
Body: <pre><code>package main

import (
    &quot;fmt&quot;
)

type ISum interface {
    sum() int
}

type SumImpl struct {
    Num int
}

func (s SumImpl) sum() int {
    return s.Num
}

func main() {

    nums := []int{1, 2}
    variadicExample1(nums...)

    impl1 := SumImpl{Num: 1}
    impl2 := SumImpl{Num: 2}

    variadicExample2(impl1, impl2)

    impls := []SumImpl{
        {
            Num: 1,
        },
        {
            Num: 2,
        },
    }
    variadicExample2(impls...)
}

func variadicExample1(nums ...int) {
    fmt.Print(nums, &quot; &quot;)
    total := 0
    for _, num := range nums {
        total += num
    }
    fmt.Println(total)
}

func variadicExample2(nums ...ISum) {

    fmt.Print(nums, &quot; &quot;)
    total := 0
    for _, num := range nums {
        total += num.sum()
    }
    fmt.Println(total)
}
</code></pre>
<p>I have a question while using variable functions in go language.</p>
<p>When passing a struct that implements an interface as an argument, individual declarations are possible, but can you tell me why it is not possible when passing it through ...?</p>
