Title: segfault when calling two function in one expression of the range-for loop C++.
Body: <p>I have big program, it does exactly like the mini version of the following code:</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;set&gt;

using namespace std;

map&lt;int,set&lt;size_t&gt;&gt; getMap(void) {
    return map&lt;int,set&lt;size_t&gt;&gt;{
        {1,{2,3,4,5}},
        {2,{3,4,5,6}}
    };
}

int getIndex(void) {
    return 1;
}

int main(void) {
    for (const size_t &amp;n: getMap()[getIndex()])
        cout &lt;&lt; n &lt;&lt; endl;

    return 0;
}
</code></pre>
<p>the result I got is a segmentation fault. I made mistake here, but don't know exactly where the mistake is. <code>getMap()[getIndex()])</code> is the experssion that I considered to be the error. But I believed the expression should be return a container <code>set&lt;size_t&gt;</code>, which I can iterate through.</p>
<p>Can someone explain why calling those function in one expression produce segmentation fault on the above code ? Did I try to access something that shouldn't be accessed?  Or I missed how the compiler behave when processing such an expression?</p>

Title: Typescript: Ensure all properties use the same tuple type.
Body: <p>I've got a function with a generic that is a tuple of 1 or a tuple of 2 elements.<br />
I want to ensure that all properties used in the function use the same length tuple.</p>
<pre class="lang-js prettyprint-override"><code>type TypeA = [string] // Tuple of 1 element
type TypeB = [string, string] // Tuple of 2 elements
type Header = TypeA | TypeB

interface SomeObject&lt;H extends Header&gt; {
    prop1: H
    prop2: H
}

function useHeader&lt;H extends Header&gt;(someObject:SomeObject&lt;H&gt;) {
    // do something
}

useHeader({
    prop1: [&quot;tuple of 1 element&quot;],
    prop2: [
        &quot;tuple of&quot;, 
        &quot;2 elements&quot;
    ] // &lt;-- I want an error here, because prop1 and prop2 use diffrent tuples
})
</code></pre>
<p>I noticed that when I change <code>TypeA</code> to <code>number</code> and <code>TypeB</code> to <code>string</code>, then Typescript gives an error when I mix numbers and strings.<br />
Is it possible to make Typescript generate an error when tuples of different length are used?</p>

Title: Print sequence of tuples before returning a value for valid transactions.
Body: <p>You are given a matrix <code>V</code> of dimensions <code>m × n</code>, where each element represents the prices of m different vegetables seeds for n consecutive days in a produce market. Furthermore, you are given an integer <code>t (1 ≤ n)</code>, which is the max number of transaction you can perform in the matrix <code>V</code>. Now print a sequence of at most t transactions, each involving the purchase and sale of a vegetable seed, that yields the maximum profit after trading seeds. Note, you must buy a seed before selling, but you can only buy another (or same) seed on or after the sell day. If you can't get any profits from selling the seeds, print <code>(0,0,0,0)</code> else print a list of tuples like this <code>[(seed type index, buy day index, sell day index, profit yield)...]</code> before returning the total profit value.</p>
<pre><code>Example:
t = 3 (at most 3 transactions are allowed)
V = [[2, 6, 3],
     [4, 2, 8]]

Result:
Total profit yield returned is 10. Tuples: Buy seed type 0 on day 0 then sell 
it on day 1 which gives value of 4 (6-4). Then, buy seed type 1 on day 1 then
sell on day 2 which gives value of 6 (8-2). 

The final output should be:
[(0,0,1,4),(1,1,2,6)] 
10
</code></pre>
<p>Currently, code gives total profit yield value. I can't figure out how to print tuples to print all the transactions that give 10. I need to maintain the time complexity of O(m<em>n</em>t). Any guidance will be appreciated.</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;tuple&gt;
#include &lt;algorithm&gt;
#include &lt;climits&gt;  

using namespace std;

int seeding(vector&lt;vector&lt;int&gt;&gt; V, int t) {

    int cols = V[0].size();
    int rows = V.size();

    vector&lt;vector&lt;int&gt;&gt; profits_table(t + 1, vector&lt;int&gt;(cols, 0));

    vector&lt;std::tuple&lt;int, int, int, int&gt;&gt; tuple_result;
    tuple_result.push_back(std::make_tuple(0, 0, 0, 0));

    vector&lt;int&gt; max_diff(rows, 0);

    int tempMax = 0;

    for (int i = 1; i &lt; t + 1; i++) {


        for (int j = 0; j &lt; rows; j++) {
            max_diff[j] = -V[j][0];
        }


        for (int j = 1; j &lt; cols; j++) {

            for (int k = 0; k &lt; rows; k++) {


                tempMax = max(tempMax, V[k][j] + max_diff[k]);

                profits_table[i][j] = max(profits_table[i][j - 1], tempMax);

                max_diff[k] = max(max_diff[k], profits_table[i - 1][j] - V[k][j]);


                //for (const auto&amp; t : tuple_result)
                //    if (profits_table[i][j] &gt; get&lt;3&gt;(t)) {
                //        tuple_result.push_back(make_tuple(i , distance(V[i].begin(), find(V[i].begin(), V[i].end(), abs(max_diff[k]))),
                //                            j + 1, profits_table[i][j]));

                //    }


            }

            tempMax = 0;
        }
    }

    // cout &lt;&lt; &quot;[&quot;
    //for (const auto&amp; tt : tuple_result)
    //{
    //    cout &lt;&lt; &quot;(&quot; &lt;&lt; get&lt;0&gt;(tt) &lt;&lt; &quot;, &quot; &lt;&lt; get&lt;1&gt;(tt) &lt;&lt; &quot;, &quot; &lt;&lt;
    //        get&lt;2&gt;(tt) &lt;&lt; &quot;, &quot; &lt;&lt; get&lt;3&gt;(tt) &lt;&lt; &quot;)&quot; &lt;&lt; endl;
    //}
    // cout &lt;&lt; &quot;]&quot;

    return profits_table[t][cols - 1];
}

int main()
{
    vector&lt;vector&lt;int&gt;&gt; V = { {2, 6, 3},
                           {4, 2, 8 } };
    int k = 3;

    cout &lt;&lt; seeding(V, k) &lt;&lt; endl;
    return 0;
}
</code></pre>

Title: strange behaviour of operator &amp;&amp; in constexpr context.
Body: <p>The following code tries to make compile-time decisions based on the last argument passed in a parameter pack. It contains a comparison if the number of parameter-pack arguments is &gt; 0 and then tries to get the last element of it. However, the constructed tuple is accessed at an invalid index which is supposedly bigger than the max tuple index (as the <code>static_assert</code> shows).<br />
How is that possible if I do <code>cnt-1</code>?</p>
<p><a href="https://godbolt.org/#g:!((g:!((g:!((h:codeEditor,i:(filename:%271%27,fontScale:14,fontUsePx:%270%27,j:1,lang:c%2B%2B,selection:(endColumn:2,endLineNumber:26,positionColumn:2,positionLineNumber:26,selectionStartColumn:1,selectionStartLineNumber:1,startColumn:1,startLineNumber:1),source:%27%23include+%3Ccstdio%3E%0A%23include+%3Cconcepts%3E%0A%23include+%3Cutility%3E%0A%23include+%3Ctuple%3E%0A%23include+%22inttypes.h%22%0A%0A%0Atemplate+%3Ctypename...+Args%3E%0Aauto+foo(Args%26%26...+args)%0A%7B%0A++++auto+tuple+%3D+std::forward_as_tuple(std::forward%3CArgs%3E(args)...)%3B%0A++++constexpr+std::size_t+cnt+%3D+sizeof...(Args)%3B%0A%0A++++if+constexpr+(cnt+%3E+0+%26%26+std::same_as%3Cstd::remove_cvref_t%3Cstd::tuple_element_t%3Ccnt-1,+decltype(tuple)%3E%3E,+int%3E)+%7B%0A++++++++printf(%22last+is+int%5Cn%22)%3B%0A++++%7D+else+%7B%0A++++++++printf(%22last+is+not+int%5Cn%22)%3B%0A++++%7D%0A%7D%0A%0Aint+main()%0A%7B%0A++++foo(2)%3B%0A%0A++++foo()%3B%0A%7D%27),l:%275%27,n:%270%27,o:%27C%2B%2B+source+%231%27,t:%270%27)),k:50,l:%274%27,n:%270%27,o:%27%27,s:0,t:%270%27),(g:!((h:executor,i:(argsPanelShown:%271%27,compilationPanelShown:%270%27,compiler:gsnapshot,compilerOutShown:%270%27,execArgs:%27%27,execStdin:%27%27,fontScale:14,fontUsePx:%270%27,j:1,lang:c%2B%2B,libs:!(),options:%27-std%3Dc%2B%2B20+-Wall%27,source:1,stdinPanelShown:%271%27,tree:%271%27,wrap:%271%27),l:%275%27,n:%270%27,o:%27Executor+x86-64+gcc+(trunk)+(C%2B%2B,+Editor+%231)%27,t:%270%27)),header:(),k:50,l:%274%27,m:100,n:%270%27,o:%27%27,s:0,t:%270%27)),l:%272%27,n:%270%27,o:%27%27,t:%270%27)),version:4" rel="nofollow noreferrer">Demo</a></p>
<pre><code>#include &lt;cstdio&gt;
#include &lt;concepts&gt;
#include &lt;utility&gt;
#include &lt;tuple&gt;


template &lt;typename... Args&gt;
auto foo(Args&amp;&amp;... args)
{
    auto tuple = std::forward_as_tuple(std::forward&lt;Args&gt;(args)...);
    constexpr std::size_t cnt = sizeof...(Args);

    if constexpr (cnt &gt; 0 &amp;&amp; std::same_as&lt;std::remove_cvref_t&lt;std::tuple_element_t&lt;cnt-1, decltype(tuple)&gt;&gt;, int&gt;) {
        printf(&quot;last is int\n&quot;);
    } else {
        printf(&quot;last is not int\n&quot;);
    }
}

int main()
{
