    my ($q2, $q1) = (pop(@stack),pop(@stack));

    #https://www.euclideanspace.com/maths/algebra/
    #realNormedAlgebra/quaternions/arithmetic/
    @q[0] = (@$q1[0] * @$q2[0] - @$q1[1] * @$q2[1] - 
    @$q1[2] * @$q2[2] - @$q1[3] * @$q2[3]);
    @q[1] = (@$q1[1] * @$q2[0] + @$q1[0] * @$q2[1] + 
