    @sudo $(FLASH) $(FLASH_FLAGS) -U flash:w:$(OUTPUT_DIR)/$(PROGRAM).hex
    @printf &quot;[FLASHED]\t$&lt;!\n&quot;

.PHONY: all clean flash
</code></pre>
