        code: 400,
        message: 'Invalid label: SENT',
        errors: [
          {
            message: 'Invalid label: SENT',
            domain: 'global',
            reason: 'invalidArgument'
          }
        ],
        status: 'INVALID_ARGUMENT'
      }
</code></pre>

