    }

    long cx = 0;
    for (long i = 0; i &lt; numOfBits; i += 8) {
        int bs[8];
        for (int a = 0; a &lt; 8; a++) {
            bs[a] = bits[i + a];
        }
        dst[cx] = encodeBitsArr(bs);
        cx++;
    }
    return cx;
}

uint32_t encodeBits(int arr[], int n) {
    uint32_t ret = 0;
    for (int i = 0; i &lt; n; i++) {
        if (arr[i] == 1) {
            ret += pow(2, i);
        }
    }

    return ret;
}

uint8_t encodeBitsArr(const int arr[8]) {
    uint8_t ret = 0;
    for (int i = 0; i &lt; 8; i++) {
        if (arr[i] == 1) {
            ret += pow(2, i);
        }
    }

    return ret;
}

void decodeBits(uint32_t b, int n, int bits[]) {
    for (int i = 0; i &lt; n; i++) {
        bits[i] = (int) ((b &gt;&gt; i) &amp; ONE_BIT_MASK_32BITS) != 0;
    }
}

void decodeBitsFromByte(uint8_t b, int bits[]) {
    for (int i = 0; i &lt; 8; i++) {
        bits[i] = (int) ((b &gt;&gt; i) &amp; 0x01) != 0;
    }
}

int findMatchingSymbol(const int bits[MAX_TREE_HT], HuffmanDictionary *dictionary,int* foundSize) {
    for (int i = 0; i &lt; 256; i++) {
        int bs[MAX_TREE_HT];
        decodeBits(dictionary-&gt;code[i].code, dictionary-&gt;code[i].size, bs);
        bool found = false;
        for (int a = 0; a &lt; dictionary-&gt;code[i].size; a++) {
            if (bs[a] == bits[a]) {
                found = true;
            } else {
                found = false;
                break;
            }
        }

        if (found) {
            *foundSize = dictionary-&gt;code[i].size - 1;
            return dictionary-&gt;symbol[i];
        }
    }

    return -1;
}

long huffman_extract(const uint8_t *src, long size, uint8_t *dst, HuffmanDictionary *dictionary) {
    uint8_t *bits = malloc(size * 8);
    memset(bits, 0, size * 8);

    for (long i = 0; i &lt; size; i++) {
        int bs[8];
        decodeBitsFromByte(src[i], bs);
        for (int a = 0; a &lt; 8; a++) {
            bits[(i * 8) + a] = bs[a];
        }
    }

    long foundBytes = 0;
    int bs[MAX_TREE_HT];
    for (long l = 0; l &lt; size * 8; l++) {
        for (int a = 0; a &lt; MAX_TREE_HT; a++) {
            bs[a] = bits[l + a];
        }
        int* foundSize = malloc(sizeof(int));

        uint8_t b = findMatchingSymbol(bs, dictionary, foundSize);
        if (b &gt;= 0) {
            dst[foundBytes] = b;
            l+= *foundSize;
            foundBytes++;
        }
    }

    return foundBytes;
}

void buildFrequencyData(const uint8_t *src, long size, FreqencyData *fd) {
    for (long i = 0; i &lt; size; i++) {
        fd[src[i]].frequency++;
    }
}

struct MinHeapNode *newNode(uint8_t data, unsigned freq) {
    struct MinHeapNode *temp = (struct MinHeapNode *)malloc(
            sizeof(struct MinHeapNode));

    temp-&gt;left = temp-&gt;right = NULL;
    temp-&gt;data = data;
    temp-&gt;freq = freq;

    return temp;
}

struct MinHeap *createMinHeap(unsigned capacity) {
    struct MinHeap *minHeap
            = (struct MinHeap *) malloc(sizeof(struct MinHeap));

    minHeap-&gt;size = 0;
    minHeap-&gt;capacity = capacity;
    minHeap-&gt;array = (struct MinHeapNode **)malloc(
            minHeap-&gt;capacity * sizeof(struct MinHeapNode *));
    return minHeap;
}

void swapMinHeapNode(struct MinHeapNode **a,
                     struct MinHeapNode **b) {
    struct MinHeapNode *t = *a;
    *a = *b;
    *b = t;
}

void minHeapify(struct MinHeap *minHeap, int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;

    if (left &lt; minHeap-&gt;size
        &amp;&amp; minHeap-&gt;array[left]-&gt;freq
           &lt; minHeap-&gt;array[smallest]-&gt;freq)
        smallest = left;

    if (right &lt; minHeap-&gt;size
        &amp;&amp; minHeap-&gt;array[right]-&gt;freq
           &lt; minHeap-&gt;array[smallest]-&gt;freq)
        smallest = right;

    if (smallest != idx) {
        swapMinHeapNode(&amp;minHeap-&gt;array[smallest],
                        &amp;minHeap-&gt;array[idx]);
        minHeapify(minHeap, smallest);
    }
}

int isSizeOne(struct MinHeap *minHeap) {
    return (minHeap-&gt;size == 1);
}

struct MinHeapNode *extractMin(struct MinHeap *minHeap) {
    struct MinHeapNode *temp = minHeap-&gt;array[0];
    minHeap-&gt;array[0] = minHeap-&gt;array[minHeap-&gt;size - 1];

    --minHeap-&gt;size;
    minHeapify(minHeap, 0);

    return temp;
}

void insertMinHeap(struct MinHeap *minHeap,
                   struct MinHeapNode *minHeapNode) {
    ++minHeap-&gt;size;
    int i = minHeap-&gt;size - 1;

    while (i
           &amp;&amp; minHeapNode-&gt;freq
              &lt; minHeap-&gt;array[(i - 1) / 2]-&gt;freq) {

        minHeap-&gt;array[i] = minHeap-&gt;array[(i - 1) / 2];
        i = (i - 1) / 2;
    }

    minHeap-&gt;array[i] = minHeapNode;
}

void buildMinHeap(struct MinHeap *minHeap) {
    int n = minHeap-&gt;size - 1;
    int i;

    for (i = (n - 1) / 2; i &gt;= 0; --i)
        minHeapify(minHeap, i);
}

int isLeaf(struct MinHeapNode *root) {
    return !(root-&gt;left) &amp;&amp; !(root-&gt;right);
}

struct MinHeap *createAndBuildMinHeap(uint8_t data[],
                                      int freq[], int size) {
    struct MinHeap *minHeap = createMinHeap(size);

    for (int i = 0; i &lt; size; ++i)
        minHeap-&gt;array[i] = newNode(data[i], freq[i]);

    minHeap-&gt;size = size;
    buildMinHeap(minHeap);

    return minHeap;
}

struct MinHeapNode *buildHuffmanTree(uint8_t data[],
                                     int freq[], int size) {
    struct MinHeapNode *left, *right, *top;

    struct MinHeap *minHeap
            = createAndBuildMinHeap(data, freq, size);

    while (!isSizeOne(minHeap)) {
        left = extractMin(minHeap);
        right = extractMin(minHeap);

        top = newNode('$', left-&gt;freq + right-&gt;freq);

        top-&gt;left = left;
        top-&gt;right = right;

        insertMinHeap(minHeap, top);
    }

    return extractMin(minHeap);
}
</code></pre>
<p>I didn't try anything as the code is running normally on other computers, but no on mine.</p>

Title: Indicating the end of a raw data chunk in an RLE algorithm that can contain all byte values.
Body: <p>I'm writing an RLE algorithm in C# that can work on any file as input. The approach to encoding I'm taking is as follows:</p>
<p>An RLE packet contains 1 byte for the length and 1 byte for the value. For example, if the byte <code>0xFF</code> appeared 3 times in a row, <code>0x03 0xFF</code> would be written to the file.</p>
<p>If representing the data as raw data would be more efficient, I use <code>0x00</code> as a terminator. This works because the length of a packet can never be zero. If I wanted to add the bytes <code>0x53 0x2C 0x01</code> to my compressed file it would look like this:</p>
<p><code>0x03 0xFF 0x00 0x53 0x2C 0x01</code></p>
<p>However a problem arises when trying to switch back to RLE packets. I can't use a byte as a terminator like I did for switching onto raw data because any byte value from <code>0x00 to 0xFF</code> can be in the input data, and when decoding the bytes the decoder would misinterpret the byte as a terminator and ruin everything.</p>
<p>What can I do to indicate that I have to switch back to RLE packets when it can't be written as data in the file?</p>
<p>Here is my code if it helps:</p>
<pre><code>private static void RunLengthEncode(ref byte[] bytes)
{
    // Create a list to store the bytes
    List&lt;byte&gt; output = new List&lt;byte&gt;();

    byte runLengthByte;
    int runLengthCounter = 0;

    // Set the RLE byte to the first byte in the array and increment the RLE counter
    runLengthByte = bytes[0];

    // For each byte in the input array...
    for (int i = 0; i &lt; bytes.Length; i++)
    {
        if (runLengthByte == bytes[i] || runLengthCounter == 255)
        {
            runLengthCounter++;
        }
        else 
        {
            // RLE packets under 3 should be written as raw data to avoid increasing the file size
            if (runLengthCounter &lt; 3)
            {
                // Add a 0x00 to indicate raw data
                output.Add(0x00);

                // Add the bytes that were skipped while counting the run length
                for (int j = i - runLengthCounter; j &lt; i; j++)
                {
                    output.Add(bytes[j]);
                }
            }
            else
            {
                // Add 2 bytes, one for the number of bytes and one for the value
                output.Add((byte)runLengthCounter);
                output.Add(runLengthByte);
            }

            runLengthCounter = 1;
            runLengthByte = bytes[i];
        }

        // Add the last bytes to the list when finishing
        if (i == bytes.Length - 1)
        {
            // Add 2 bytes, one for the number of bytes and one for the value
            output.Add((byte)runLengthCounter);
            output.Add(runLengthByte);
        }
    }

    // Set the bytes to the RLE encoded data
    bytes = output.ToArray();
}
</code></pre>
<p>Also if you want to comment and say that RLE isn't very efficient for binary data, I know it isn't. This is a project I'm doing to implement many kinds of compression to learn about them, not for an actual product.</p>
<p>Any help would be appreciated! Thanks!</p>

Title: R Function For Coupon Collector&#39;s Function with Finite Number of Trials.
Body: <p>I'm trying to write up a function that runs the Coupon Collector's Problem in R. I'm trying to make a function that will spit out the number of unique coupons collected from sample size n with a finite number of trials t. (For example, having 500 unique coupons in a sample space, and picking a coupon from it 1000 times with replacement.)</p>
<p>I was able to write a similar function that returns how many times you have to sample it to collect ALL tickets. However, that function only requires specifying n, and does not account for the finite number of trials.</p>
<p>So far, this is how I have attempted to go about writing this function, with the function calling for n and t.</p>
<p>I assumed that if the length of the trials was less than t for the while loop, I could keep counting the unique coupons until trials == t, then return the number x out of n tickets collected after t trials. So far, all R has done is stall indefinitely.</p>
<pre><code>Collectathon2 &lt;- function(n, t){
      Coupons &lt;- 1:n
      Collected_Coupons &lt;- c()
      Trials &lt;- 0

      while (length(Trials) &lt; t) {
        New_Coupon &lt;- sample(n, 1)
        Collected_Coupons &lt;- unique(c(Collected_Coupons, New_Coupon))
        Unique_Coupons &lt;- length(Collected_Coupons)
        Trials &lt;- Trials + 1
      }
      return(Unique_Coupons)
    }
</code></pre>
<p>I assumed I would only need to modify this function below, which will run until it gets all of the tickets. This one works and spits a number out pretty quickly.</p>
<pre><code>Collectathon &lt;- function(n){
      Collected_Coupons &lt;- c()
      Trials &lt;- 0

      while (length(Collected_Coupons) &lt; n) {
        New_Coupon &lt;- sample(n, 1)
        Collected_Coupons &lt;- unique(c(Collected_Coupons, New_Coupon))
        Trials &lt;- Trials + 1
        }
      return(Trials)
    }
</code></pre>

Title: Monthly Celery Beat task also runs after celery restart.
Body: <p>I have a task that is set to run on the first day of every month at 05:00 using celery beat. It has been set as follows in settings.py:</p>
<pre><code>CELERY_BEAT_SCHEDULE = {
        'generate_monthly_reports': {
            'task': 'api.tasks_reports.generate_monthly_reports',
            'schedule': crontab(minute=0, hour=5, day_of_month=1)
        },
    }
</code></pre>
<p>This works well and runs reliably. However, I have recently discovered that it is also run whenever Celery is restarted, e.g. when a server code update is made and celery restarted via supervisor. I am using Celery 5.2.6, Python 3.8 and Django 4.0.4.</p>
<p>How can I prevent this task running when Celery is restarted please?</p>

Title: Celery&#39; pytest fixtures don&#39;t work as expected during http request.
Body: <p>everyone.</p>
<p>Probably I'm missing somethig on how to use celery' pytest fixtures during a test that involves a task execution during an http request. Celery' docs that shows the pytest integration: <a href="https://docs.celeryq.dev/en/v5.3.4/userguide/testing.html#pytest" rel="nofollow noreferrer">https://docs.celeryq.dev/en/v5.3.4/userguide/testing.html#pytest</a></p>
<p>Using 'celery_session_app' and 'celery_session_worker' fixtures I can directly call the task and use <code>wait()</code> or <code>get()</code> to wait for task execution. Sample code for this case:</p>
<pre class="lang-py prettyprint-override"><code>from django.core import mail
from django.test import TestCase
from polls.tasks import task_send_mail


@pytest.mark.usefixtures('celery_session_app')
@pytest.mark.usefixtures('celery_session_worker')
class SendMailTestCase(TestCase):
    def test_send_mail(self):
        task: AsyncResult = task_send_mail.delay(
            email_address='mail@mail.org.br',
            message='Hello'
        )

        # waits for task execution that just sends a simple mail using
        # from django.core.mail import send_mail
        task.get()

        # it passes because the code waited for mail send
        self.assertEqual(len(mail.outbox), 1)
</code></pre>
<p>However, if I call the same task inside a django view, the task is executed assynchronous and the test fails because the assert is tested before the mail is sent.</p>
<pre class="lang-py prettyprint-override"><code># view

from rest_framework import serializers
from rest_framework.generics import ListAPIView
from rest_framework.response import Response
from django.contrib.auth.models import Group
from polls.tasks import task_send_mail

class GroupSerializer(serializers.ModelSerializer):
    class Meta:
        model = Group
        fields = ['__all__']


class GroupView(ListAPIView):
    http_method_names = [&quot;get&quot;]
    queryset = Group.objects.all()
    serializer_class = GroupSerializer

    def get(self, request, *args, **kwargs):
        # task is sent to async execution
        task = task_send_mail.delay(
            email_address='mail@mail.org.br',
            message='hello'
        )
        return Response(
            status=200,
            data={}
        )
</code></pre>
<p>And when pytest executes the test...</p>
<pre class="lang-py prettyprint-override"><code>from django.core import mail
from django.test import TestCase
from polls.tasks import task_send_mail

@pytest.mark.usefixtures('celery_session_app')
@pytest.mark.usefixtures('celery_session_worker')
class SendMailTestCase(TestCase):

    def test_request_url(self):
        response = self.client.get(
            reverse('groups')
        )
        self.assertEqual(
            response.status_code,
            200
        )
        self.assertEqual(
            len(mail.outbox),
            1
        )
</code></pre>
<p>It returns a failed result <code>AssertionError: 0 != 1</code> because the tasks was sent to async execution and is not complete when the assert is made.</p>
<p>The only way I found to solve this problem is changing celery config fixture inside the conftest.py file:</p>
<pre class="lang-py prettyprint-override"><code>import pytest

@pytest.fixture(scope='session')
def celery_config():
    return {
        'task_always_eager': True
    }
</code></pre>
<p>Is there a way to always wait for async task execution without set 'task_always_eager'?</p>
<p>I expected that as I'm using <code>celery_session_app</code> and <code>celery_session_worker</code> fixtures as decorators for the TestCase class, the code would wait for every async task sent to execution to finish before keeps the code execution.</p>

Title: CUDA why just reading (zero write) from unified memory cause next kernel to become slower.
Body: <pre><code>#include &lt;cuda_runtime.h&gt;
#include &lt;string&gt;
#include &lt;chrono&gt;
#include &lt;random&gt;
#include &lt;iostream&gt;
using namespace std;

class MyTimer {
  std::chrono::time_point&lt;std::chrono::system_clock&gt; start;

public:
  void startCounter() {
      start = std::chrono::system_clock::now();
  }

  int64_t getCounterNs() {
      return std::chrono::duration_cast&lt;std::chrono::nanoseconds&gt;(std::chrono::system_clock::now() - start).count();
  }

  int64_t getCounterMs() {
      return std::chrono::duration_cast&lt;std::chrono::milliseconds&gt;(std::chrono::system_clock::now() - start).count();
  }

  double getCounterMsPrecise() {
      return std::chrono::duration_cast&lt;std::chrono::nanoseconds&gt;(std::chrono::system_clock::now() - start).count()
              / 1000000.0;
  }
};

__global__ void HelloWorld();
void GenData(int N, float* a);
__global__ void Multiply(int N, float* __restrict__ output, const float* __restrict__ x, const float* __restrict__ y);

//----------
volatile double dummy = 0;

void Test(bool summing)
{
  MyTimer timer;

  int N = 10000000;
  float *d_x, *d_y, *d_res;
  cudaMallocManaged(&amp;d_x, N * sizeof(float));
  cudaMallocManaged(&amp;d_y, N * sizeof(float));
  cudaMallocManaged(&amp;d_res, N * sizeof(float));
  cudaMemAdvise(d_res, N * sizeof(float), cudaMemAdviseSetAccessedBy, cudaCpuDeviceId);  // set direct access hint

  GenData(N, d_x);
  GenData(N, d_y);
  GenData(N, d_res);

  cudaMemPrefetchAsync(d_x, N * sizeof(float), 0, 0);
  cudaMemPrefetchAsync(d_y, N * sizeof(float), 0, 0);
  cudaMemPrefetchAsync(d_res, N * sizeof(float), 0, 0);
  cudaDeviceSynchronize();

  //-------------------
  int nloop = 100;
  double cost = 0;
  for (int t = 1; t &lt;= nloop; t++) {
    timer.startCounter();
    Multiply&lt;&lt;&lt;256,256&gt;&gt;&gt;(N, d_res, d_x, d_y);
    cudaDeviceSynchronize();
    dummy = timer.getCounterMsPrecise();
    cost += dummy;

    // This only read data, and doesn't write.
    // Why does it still invalidate d_res memory pages on the GPU ?
    // Is there any way to read data from d_res without making the next kernel call slower?
    float sum = rand() % 1000;
    if (summing) {
      // either line below will make the next kernel slower
      cudaMemPrefetchAsync(d_res, N * sizeof(float), cudaCpuDeviceId, 0);
      //for (int i = 0; i &lt; N; i++) sum += d_res[i];
    }
    cudaDeviceSynchronize();
    dummy = sum;
  }

  cout &lt;&lt; &quot;Summing = &quot; &lt;&lt; summing &lt;&lt; &quot; cost = &quot; &lt;&lt; cost / nloop &lt;&lt; &quot;\n&quot;;
  cudaFree(d_x);
  cudaFree(d_y);
  cudaFree(d_res);
}

int main()
{
  srand(time(NULL));
  HelloWorld&lt;&lt;&lt;1,1&gt;&gt;&gt;();

  Test(false);
  Test(true);
  Test(false);
  Test(true);
  return 0;
}


//-----------------------------
//-----------------------------
//-----------------------------
__global__
void HelloWorld()
{
printf(&quot;Hello world\n&quot;);
}

void GenData(int N, float* a)
{
  for (int i = 0; i &lt; N; i ++) a[i] = float(rand() % 1000) / (rand() % 1000 + 1);
}

__global__
void Multiply(int N, float* __restrict__ output, const float* __restrict__ x, const float* __restrict__ y)
{
  int start = blockIdx.x * blockDim.x + threadIdx.x;
  int stride = blockDim.x * gridDim.x;

  for (int i = start; i &lt; N; i += stride) {
    output[i] = x[i] * y[i];
  }
}

</code></pre>
<p>Compile command: <code>nvcc -o main main.cu -O3 -std=c++17</code>, 2080ti
Output:</p>
<pre><code>Hello world
Summing = 0 cost = 0.237617
Summing = 1 cost = 12.1865
Summing = 0 cost = 0.235626
Summing = 1 cost = 11.8909
</code></pre>
<p>I have a bunch of Unified Memory (UM) GPU array (like Matlab's <code>gpuArray</code>). 99.9% of the computation/write operations will be done on the GPU device memory. Sometimes the result is read on CPU.</p>
<p>I notice that just reading a UM array on CPU side will cause the next kernel call on that array to become much slower. <strong>I assume this is due to some kind of page fault. But usually only memory writes cause page faults.</strong></p>
<p>Why does this happen? How can I change the code so that reading from UM doesn't make the next kernel slower? (edit: without using <code>cudaMemPrefetch</code>, if possible)</p>
<p>Edit: also, <code>directManagedMemAccessFromHost</code> gives 0 on 2080ti and Nvidia A30. So which system support that feature?</p>

