Title: What is the problem with my code(bandwidth limitation)?.
Body: <p>I'm now making a broadcasting web using socket.io and webRTC. I can successly broadcast the video stream from the broadcaster to the viewers. However, I want to limit the bandwidth of the viewers/broadcasters so that if more viewers/broadcaster join the server, the quality of the video can be reduced to allow more users. It seems that I cannot change the videoWidth and videoHeight as they are read-only so I cannot directly change the resolution of the video. So I wonder if I can setBitrate to limit the performance of the video.</p>
<p>server.js</p>
<pre><code>const express = require(&quot;express&quot;);
const app = express();

let broadcaster;
const port = 4000;

const http = require(&quot;http&quot;);
const server = http.createServer(app);

const io = require(&quot;socket.io&quot;)(server);
app.use(express.static(__dirname + &quot;/public&quot;));

io.sockets.on(&quot;error&quot;, e =&gt; console.log(e));
io.sockets.on(&quot;connection&quot;, socket =&gt; {
  socket.on(&quot;broadcaster&quot;, () =&gt; {
    broadcaster = socket.id;
    socket.broadcast.emit(&quot;broadcaster&quot;);
  });
  socket.on(&quot;watcher&quot;, () =&gt; {
    socket.to(broadcaster).emit(&quot;watcher&quot;, socket.id);
  });
  socket.on(&quot;offer&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;offer&quot;, socket.id, message);
  });
  socket.on(&quot;answer&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;answer&quot;, socket.id, message);
  });
  socket.on(&quot;candidate&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;candidate&quot;, socket.id, message);
  });
  socket.on(&quot;disconnect&quot;, () =&gt; {

    if (socket.id === broadcaster) {

      socket.broadcast.emit(&quot;disconnectServer&quot;);
    }

    socket.broadcast.emit(&quot;disconnectPeer&quot;, socket.id);
  });
});
server.listen(port, () =&gt; console.log(`Server is running on port ${port}`));
</code></pre>
<p>broadcast.js</p>
<pre><code>const peerConnections = {};
const config = {
  iceServers: [
    {
      &quot;urls&quot;: &quot;stun:stun.l.google.com:19302&quot;
    }
  ],
  sdpSemantics: &quot;plan-b&quot;
};

function setBitrate(sdp, bitrate) {
  return sdp.replace(/a=mid:(audio|video)\r\n/g, `a=mid:$1\r\nb=AS:${bitrate}\r\n`);
}



const socket = io.connect(window.location.origin);
const video = document.querySelector(&quot;video&quot;);


// Media contrains
function getStream() {
  if (window.stream) {
    window.stream.getTracks().forEach(track =&gt;{
      track.stop();
    });
  }
  const constraints = {
    video: true,
    audio: true,
    width: {exact:320},
    height: {exact:240},
    aspectRatio: 16/9,
    frameRate: {exact: 30},
    videoBitrate: 100000

  };




  navigator.mediaDevices.getUserMedia(constraints)
    .then(stream =&gt; {
      const videoTrack = stream.getVideoTracks()[0];
      const capabilities = videoTrack.getCapabilities();
      console.log(capabilities.width.max); // maximum supported width
      console.log(capabilities.height.max); // maximum supported height
    })
    .catch(error =&gt; {
      // handle the error
    });
  video.addEventListener(&quot;loadedmetadata&quot;, function(){
    console.log(&quot;VideoWidth: &quot; + video.videoWidth + &quot; VideoHeight: &quot; + video.videoHeight);
  })


  return navigator.mediaDevices
    .getUserMedia(constraints)
    .then(gotStream)
    .catch(handleError);
}




function gotStream(stream){ 
  window.stream = stream;
  video.srcObject = stream;
  socket.emit(&quot;broadcaster&quot;);
}



function handleError(error) {
  console.error(&quot;Error: &quot;, error);
}


function setdefaultscreen(){
  video.srcObject = null;
  video.style.backgroundColor = &quot;black&quot;;
}

socket.on(&quot;watcher&quot;, id =&gt; {
  console.log(&quot;viewerConnect!!&quot;);
  const peerConnection = new RTCPeerConnection(config);
  peerConnections[id] = peerConnection;

  let stream = video.srcObject;
  stream.getTracks().forEach(track =&gt; peerConnection.addTrack(track, stream));

  peerConnection.onicecandidate = event =&gt; {
    if (event.candidate) {
      socket.emit(&quot;candidate&quot;, id, event.candidate);
    }
  };

  peerConnection
    .createOffer()
    .then(sdp =&gt; {
      sdp.sdp = setBitrate(sdp.sdp, 5);
      return peerConnection.setLocalDescription(sdp)})
    .then(() =&gt; {
      socket.emit(&quot;offer&quot;, id, peerConnection.localDescription);
    });
});

socket.on(&quot;answer&quot;, (id, description) =&gt; {
  peerConnections[id].setRemoteDescription(description);
});

socket.on(&quot;candidate&quot;, (id, candidate) =&gt; {
  peerConnections[id].addIceCandidate(new RTCIceCandidate(candidate));
});

socket.on(&quot;disconnect&quot; ,() =&gt;{
  socket.emit(&quot;disconnect&quot;);
  console.log(&quot;disconnect from server&quot;);
  if (peerConnection) {
    peerConnection.close();
  }
  setdefaultscreen();
})

socket.on(&quot;disconnectPeer&quot;, id =&gt; {
  console.log(&quot;disconnect peer from client&quot;);
  peerConnections[id].close();
  delete peerConnections[id];
});


window.onunload = window.onbeforeunload = () =&gt; {
  socket.close();
};


getStream();
</code></pre>
<p>viewer.js</p>
<pre><code>let peerConnection;
const config = {
  iceServers: [
      { 
        &quot;urls&quot;: &quot;stun:stun.l.google.com:19302&quot;,
      },
      // { 
      //   &quot;urls&quot;: &quot;turn:TURN_IP?transport=tcp&quot;,
      //   &quot;username&quot;: &quot;TURN_USERNAME&quot;,
      //   &quot;credential&quot;: &quot;TURN_CREDENTIALS&quot;
      // }
  ],
  sdpSemantics: &quot;plan-b&quot;,
};


function setBitrate(sdp, bitrate) {
  return sdp.replace(/a=mid:(audio|video)\r\n/g, `a=mid:$1\r\nb=AS:${bitrate}\r\n`);
}

const socket = io.connect(window.location.origin);
const video = document.querySelector(&quot;video&quot;);

socket.on(&quot;offer&quot;, (id, description) =&gt; {
  peerConnection = new RTCPeerConnection(config);
  peerConnection
    .setRemoteDescription(description)
    .then(() =&gt; peerConnection.createAnswer())
    .then(sdp =&gt; {
      sdp.sdp = setBitrate(sdp.sdp, 5);
      return peerConnection.setLocalDescription(sdp)}
      )
    .then(() =&gt; {
      socket.emit(&quot;answer&quot;, id, peerConnection.localDescription);
    });
  peerConnection.ontrack = event =&gt; {
    video.srcObject = event.streams[0];
  };
  peerConnection.onicecandidate = event =&gt; {
    if (event.candidate) {
      socket.emit(&quot;candidate&quot;, id, event.candidate);
    }
  };
});


socket.on(&quot;candidate&quot;, (id, candidate) =&gt; {
  peerConnection
    .addIceCandidate(new RTCIceCandidate(candidate))
    .catch(e =&gt; console.error(e));
});

socket.on(&quot;connect&quot;, () =&gt; {
  socket.emit(&quot;watcher&quot;);
});

socket.on(&quot;broadcaster&quot;, () =&gt; {

  socket.emit(&quot;watcher&quot;);
});

function setdefaultscreen(){
  video.srcObject = null;
  video.style.backgroundColor = &quot;black&quot;;
}

socket.on(&quot;disconnectServer&quot;, () =&gt; {
  console.log(&quot;disconnect from server&quot;);
  setdefaultscreen();
});

window.onunload = window.onbeforeunload = () =&gt; {
  socket.close();
  peerConnection.close();
  setdefaultscreen();


};
</code></pre>
<p>now I setBitrate to 5 and the video should be hardly playable. But I found that no matter what value I set the video is still playable and its quality doesn't change. I use Google Chrome to open the web. Is the problem related to the browser?</p>

Title: Issue with video streaming on mobile devices using Node.js and Express.
Body: <p>I'm building a video streaming server using <strong>Node.js</strong> and <strong>Express</strong>. The server works fine when I access it from a desktop browser, but I'm experiencing issues when trying to stream videos on mobile devices. The request is closed abruptly with 0 bytes read, and the video doesn't play.</p>
<p>Here's an overview of my setup:</p>
<ul>
<li><p><strong>Node.js</strong> version: 16.17.0</p>
</li>
<li><p><strong>Express</strong> version: 4.18.2</p>
</li>
<li><p><strong>Video format</strong>: mp4 (codec : H264-MPEG-4 AVC)</p>
</li>
<li><p>Chunk size: the Chunk size that i want to be streamed is 10**6 (<strong>1MB</strong>)</p>
</li>
</ul>
<p><strong>index.js</strong></p>
<pre class="lang-js prettyprint-override"><code>const express = require('express');
const path = require('path');
const fs = require('fs');

const app = express();
const port = 3333;

app.get('/', (req, res) =&gt; {
  return res.status(200).sendFile(path.join(__dirname, 'index.html'));
});

app.get('/video', (req, res) =&gt; {
  const videoPath = '&lt;VIDEO_PATH&gt;.mp4';
  const videoSize = fs.statSync(videoPath).size;

  const range = req.headers.range;
 if (!range) {
    res.status(400).send('Range header is missing');
  }
  const parts = range.replace(/bytes=/, '').split('-');
  const start = parseInt(parts[0], 10);
  const end = parts[1] ? parseInt(parts[1], 10) : videoSize - 1;
  const chunkSize = end - start + 1;

  res.status(206).header({
    'Content-Range': `bytes ${start}-${end}/${videoSize}`,
    'Accept-Ranges': 'bytes',
    'Content-Length': chunkSize,
    'Content-Type': 'video/mp4',
  });

  fs.createReadStream(videoPath, { start, end }).pipe(res);
});
app.listen(port, () =&gt; {
  console.log(`Server is running on port  ${port}`);
});

</code></pre>
<p><strong>index.html</strong></p>
<pre class="lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;meta charset=&quot;UTF-8&quot; /&gt;
    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot; /&gt;
    &lt;title&gt;Video share&lt;/title&gt;
  &lt;/head&gt;
  &lt;style&gt;
    body {
      max-width: 720px;
      margin-left: auto;
      margin-right: auto;
      background-color: lightgray;
    }
  &lt;/style&gt;
  &lt;body&gt;
    &lt;video width=&quot;420&quot; controls autoplay muted&gt;
      &lt;source src=&quot;/video&quot; type=&quot;video/mp4&quot; /&gt;
    &lt;/video&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<p>I've noticed that when I use a smaller chunk size (e.g., 10 ** 6 bytes), the video doesn't play on mobile devices. However, when I set the chunk size to <strong>end - start + 1</strong>, it works, but it loads the entire video file, and it makes only one request.</p>
<p>I've also tried adjusting the chunk size to larger values (e.g., 10 ** 7 bytes), but the problem persists.</p>
<p><strong>My question is :</strong></p>
<ol>
<li>What could be causing the issue with streaming videos on mobile devices ?</li>
<li>Why does using <strong>&quot;chunkSize = end - start + 1&quot;</strong> allow the video to stream on mobile devices, but not when using smaller chunk sizes?</li>
<li>Are there any additional considerations or best practices for video streaming on mobile devices that I might be missing?</li>
</ol>
<p>Any insights or suggestions would be greatly appreciated. <strong>Thank you!</strong></p>

Title: Unable to open socket.
Body: <p>I am trying to open a socket connection to a specific address using a class which extends Thread. The overridden run method code is</p>
