            }

        } catch(UnknownHostException e) {
            TCLog.d(TAG, &quot;value UnknownHostException&quot; + e.getMessage());
            handleError(e.getMessage());
        } catch(IOException e) {
            TCLog.d(TAG, &quot;value IOException &quot; + e.getMessage());
            handleError(e.getMessage());
        }

        try {
            printWriter = new PrintWriter(socket.getOutputStream());
            printWriter.println(serverHeader);
            printWriter.flush();
            isFirstMessage = true;
        } catch(IOException e) {
            TCLog.d(TAG, &quot;value IOException while writing &quot; + e.getMessage());
            handleError(e.getMessage());
        }

        while (!shouldCloseConnection) {
            try {
                String dataToSend = null;
                byte[] readingData = new byte[BUFFER_SIZE];
                int read;
                byte[] data = null;
                if ((read = bufferedInputStream.read(readingData)) != -1) {
                    TCLog.d(TAG, &quot;OTHER read value &quot; + read);
                    data = Arrays.copyOfRange(readingData, 0, read);
                    dataToSend = new String(data);
                }
                if (null != dataToSend) {
                    TCLog.d(TAG, &quot;message from server &quot; + dataToSend);
                    if (isFirstMessage) {

                        if (!dataToSend.contains(&quot;200 OK&quot;)) {

                            if (dataToSend.contains(&quot;303&quot;)) {

                                TCLog.d(TAG, &quot;when there is redirect&quot;);
                                TCLog.d(TAG, &quot;splitting string value&quot;);

                                String[] videos = dataToSend.split(&quot;https://&quot;);

                                TCLog.d(TAG, &quot;values 1 &quot; + videos[0]);
                                TCLog.d(TAG, &quot;value 2 &quot; + videos[1]);

                                String redirectUrl = videos[1];

                                videos = redirectUrl.split(&quot;:&quot;);

                                redirectUrl = videos[0];

                                TCLog.d(TAG, &quot;redirect URL is &quot; + redirectUrl);

                                isRedirectUrl = true;

                                this.serverAddress = redirectUrl;
                                Reflector.address = this.serverAddress;
                                break;
                            } else if (dataToSend.contains(&quot;HTTP/1.0 4&quot;)) {
                                isRedirectUrl = false;
                                break;
                            }
                        } else {
                            this.isFirstMessage = false;
                            if (null != listener) {
                                this.listener.getConnectionConnectedSuccessfully();
                            }
                        }
                    }
                    else {
                        if (null != listener) {
                            listener.getConnectionRawData(data, dataToSend.trim());
                        }
                    }
                }
            } catch(IOException e) {
                TCLog.d(TAG, &quot;value IOException while reading &quot; + e.getMessage());
                handleError(e.getMessage());
            } finally {
                TCLog.d(TAG, &quot;inside finally block&quot;);
                if (isFirstMessage &amp;&amp; !isRedirectUrl) {
                    handleError(&quot;Unable to play video&quot;);

                    if (null != printWriter) {
                        printWriter.close();
                    }
                    try {
                        TCLog.d(TAG, &quot;inside finally try block. Closing connections&quot;);
                        if (null != bufferedInputStream) {
                            bufferedInputStream.close();
                        }
                        if (null != socket &amp;&amp; socket.isConnected()) {
                            socket.close();
                        }
                    } catch(IOException e) {
                        TCLog.d(TAG, &quot;error while closing streams &quot; + e.getMessage());
                    }
                }
            }
        }
        if (!isRedirectUrl) {
            break;
        }
    }
    if (count &gt;= MAX_CONNECTION_TRY &amp;&amp; !shouldCloseConnection) {
        handleError(&quot;Unable to establish connection&quot;);
    }
}
</code></pre>
<p>The first log (media server address) gets printed, but the 2nd log does not and my socket connection goes into limbo. No code after trying to create a socket gets executed. It is not a consistent behaviour, at-times the socket connection is successful.</p>
<p>If the socket connection is successful, there is a certain GET command/call that we are supposed to make.
I tried to make the GET call as an API call/REST call and every time I got a reply from the server even if there is a delay of about 10-12 seconds which makes me believe that it is not a server config issue (I might be wrong). Any insight or any suggestion on how to proceed forward?</p>

Title: Netty TCP real-time video stream.
Body: <p>I'm trying to do a live video stream using Netty TCP.
But I found only HTTP/WEB video streams on Netty, it's all too complicated and I can't figure out what exactly I need to do.</p>
<p>My network has a packet system, and from what I understand, I have to send updated pixels of the previous frame in each packet. I've tried the Xuggler library but I haven't found any guides on how to do a live stream on it via Netty TCP.</p>
<p>I've tried to make code that get the updated pixels out of the image but it uses too much CPU time and takes too long to execute per frame.</p>
<p>My code (image resolution is 1920x1080 and it takes 20ms to execute)</p>
<pre class="lang-java prettyprint-override"><code>BufferedImage lastFrame, newFrame;
...

long time = System.currentTimeMillis();

int[][] updatedPixels = new int[newFrame.getHeight()][newFrame.getWidth()];
int[] pixels = newFrame.getRGB(0, 0, newFrame.getWidth(), newFrame.getHeight(), null, 0, newFrame.getWidth());
int index = 0, count = 0;

for (int i = 0; i &lt; newFrame.getHeight(); i++) {
  for (int j = 0; j &lt; newFrame.getWidth(); j++) {
