<pre><code>-- information_schema.columns.sql

-- name: GetTableDetail :many

SELECT table_name, column_name FROM information_schema.columns WHERE table_name = $1;
</code></pre>
<pre><code>v1Router.Post(&quot;/table&quot;, apiCfg.handlerGetTableDetail)
</code></pre>
<pre><code>func (apiCfg *apiConfig) handlerGetTableDetail(w http.ResponseWriter, r *http.Request) {

    type parameters struct {
        Table string `json:&quot;table&quot;`
    }

    decoder := json.NewDecoder(r.Body)

    params := parameters{}

    err := decoder.Decode(&amp;params)
    if err != nil {
        respondWithError(w, 400, fmt.Sprintf(&quot;Error parsing JSON : %v&quot;, err))
        return
    }

    data, err := apiCfg.DB.GetTableDetail(r.Context(), params.Table)
    if err != nil {
        respondWithError(w, 400, fmt.Sprintf(&quot;Couldn't find any data : %v&quot;, err))
        return
    }

    respondWithJSON(w, 200, data)
}
</code></pre>
