<pre><code>namespace CredentialsFactory
{
    public enum SharePointAuthentication
    {
        SharePointOnline,
        SharePointActiveDirectory
    }
    public class SharePointCredentials101
    {

        public static ICredentials CreateCredential(string UserName, string Password,
            SharePointAuthentication authenticationType)
        {
            ICredentials result = null;
            switch (authenticationType)
            {
                case SharePointAuthentication.SharePointActiveDirectory:
                    result = new NetworkCredential(UserName, Password);
                    break;

                    case SharePointAuthentication.SharePointOnline:
                    SecureString securePassword = new SecureString();
                    foreach(char ch in Password.ToCharArray())
