        perror(&quot;Connection failed&quot;);
        close(client_socket);
        exit(EXIT_FAILURE);
    }    
    else {
        printf(&quot;Fetching message ...\n&quot;);
        int rval;
        while(1) {
            rval = recv(client_socket, buf, sizeof(buf), 0);
            if(rval &lt; 0) {
