            const content = await response.json();
            console.log(content);
            setSelectedDataVideos(content);
        } catch (error) {
            console.error(error);
        }
    };
</code></pre>
<p>the console.log() of the selectedDataVideos is :</p>
<blockquote>
<p>Array (1) 0 Object</p>
<p>buffer: {type: &quot;Buffer&quot;, data: Array}</p>
<p>name: &quot;butterfly slow motion [oAI-OqTmJj4].mp4&quot;</p>
