Title: SFML render (draw) order.
Body: <p>Why is the rendering order different from what I expect it to be?</p>
<pre class="lang-cpp prettyprint-override"><code>window.draw(cell);
window.draw(player);
</code></pre>
<p>Doing this, <code>player</code> should be rendered on top of any <code>cell</code>. This is what I get though (<code>cell</code>s below the line marked are rendered <em>on top</em> of <code>player</code>) – why?:</p>
<img src="https://i.stack.imgur.com/jMNWS.png" width="250" />
<img src="https://i.stack.imgur.com/i640u.png" width="250" />
<p>
</p>
<hr />
<p>Minimal reproducible example:
<a href="https://i.stack.imgur.com/DORIb.gif" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/DORIb.gif" alt="Problem – simplified" /></a></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;SFML/Graphics.hpp&gt;

int main() {
    sf::RenderWindow window(sf::VideoMode(1280, 960), &quot;Sample&quot;);

    sf::Texture texture; texture.loadFromFile(&quot;assets/images/player.png&quot;);
    sf::Sprite sprite(texture);

    int **map = new int *[3]{new int[3]{0, 0, 0}, new int[3]{0, 0, 0}, new int[3]{0, 0, 7}};
    struct Entity { int x, y; } entity{};

    while (window.isOpen()) {
        for (auto event = sf::Event(); window.pollEvent(event);) {
            std::swap(map[entity.y][entity.x],map[entity.y - (event.type == sf::Event::KeyPressed &amp;&amp; event.key.code == sf::Keyboard::Up ? 1 : 0)][entity.x - (event.type == sf::Event::KeyPressed &amp;&amp; event.key.code == sf::Keyboard::Left ? 1 : 0)]);
        }

        window.clear(sf::Color::Black);

        float cell_size = 960.f / 19;
        for (int y = 0; y &lt; 19; ++y) {
            for (int x = 0; x &lt; 19; ++x) {
                sf::RectangleShape cell(sf::Vector2f(cell_size, cell_size));

                if (x &gt;= 3 || y &gt;= 3) {
                    continue;
                }

                switch (map[y][x]) {
                    case 0:
                        cell.setPosition(float(x) * cell_size + float(1280 - 19 * cell_size) / 2,float(y) * cell_size);
                        window.draw(cell);
                        break;

                    case 7:
                        sprite.setPosition(float(x) * cell_size, float(y) * cell_size);
                        entity = {x, y};
                        window.draw(sprite);
                        break;
                }

            }
        }

        window.display();
    }
}
</code></pre>

