Title: How to trigger cypress after:run after tests finish execution.
Body: <p>I'm using <code>cypress</code> + <code>multiple-cucumber-html-report</code> to generate a report after execution. There is the possibility to add custom data to the report such as execution start and end time.</p>
<p>I assume this information somehow comes from cypress as part of the result meta data.</p>
<p>I tried to put results in json file after the run finishes, by adding it to the cypress config file:</p>
<pre><code>import { defineConfig } from 'cypress';
import * as fs from 'fs';

async function setupNodeEvents(on, config) {

  on('after:run', async (results) =&gt; {
    if (results) {
      fs.mkdirSync(&quot;cypress/.run&quot;, { recursive: true });
      fs.writeFile(&quot;cypress/.run/results.json&quot;, JSON.stringify(results), (err) =&gt; {
        if (err)
          console.log(err);
        else {
          console.log(&quot;Successful results has been written&quot;);
        }
      });
    }
  })

  return config;
}

export default defineConfig({
  e2e: {
    setupNodeEvents,
    experimentalInteractiveRunEvents: true
  },
});
</code></pre>
<p>then read these results in the report generation file:</p>
<pre><code>const report = require('multiple-cucumber-html-reporter');
const fs = require('fs');

fs.readFile('cypress/.run/results.json', function read(err, data) {
    if (err) {
        throw err;
    }
    var runInfos = JSON.parse(data);
    report.generate({
        jsonDir: './cypress/result/',
        reportPath: './cypress/report/',
        metadata:{
            browser: {
                name: runInfos.browserName,
                version: runInfos.browserVersion
            },
            device: 'Cypress',
            platform: {
                name: mapOs(runInfos.osName)
            }
        },
        customData: {
            title: 'Run info',
            data: [
                {label: 'Project', value: 'project'},
                {label: 'Execution Start Time', value: new Date(runInfos.startedTestsAt).toLocaleString()},
                {label: 'Execution End Time', value: new Date(runInfos.endedTestsAt).toLocaleString()}
            ]
        }
    });
});
</code></pre>
<p>unfortunately the <code>after:run</code> was never triggered, and not even throwing an error.</p>

