      images: {
        url: t(&quot;Metadata.image&quot;),
      },
      app: {
        name: &quot;twitter_app&quot;,
        id: {
          iphone: &quot;twitter_app://iphone&quot;,
          ipad: &quot;twitter_app://ipad&quot;,
          googleplay: &quot;twitter_app://googleplay&quot;,
