        url: {
          iphone: &quot;https://iphone_url&quot;,
          ipad: &quot;https://ipad_url&quot;,
        },
      },
    },
    openGraph: {
      title: t(&quot;Metadata.title&quot;),
      description: t(&quot;Metadata.description&quot;),
    },
    robots: {
      index: false,
      follow: true,
