    }
    Box(
        modifier = modifier
            .clip(keyShape)
            .background(keyColor)
            .height(dimensionResource(id = R.dimen.key_height).value.dp)
            .pointerInput(Unit) {
                detectTapGestures(
                    onLongPress = {
                        onLongKeyPressed(key)
                    },
                    onPress = {
                        awaitRelease()
                        onLongKeyPressedEnd()
                    },
                    onTap = {
                        isPopupVisible.value = true
                        if (context != null) {
                            playSound(context = context)
                        }
                        if (key.label == &quot;?123&quot; || key.label == &quot;ABC&quot;) onLayoutSwitchClick()
                        else onKeyPressed(key)
                        Handler(Looper.getMainLooper()).postDelayed({
                            isPopupVisible.value = false
                        }, 250)
                    }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        if (iconResourceId != null &amp;&amp; key.contentDescription != null) {
            Icon(
                painter = painterResource(id = iconResourceId),
                contentDescription = key.contentDescription,
                tint = textColor,
                modifier = Modifier.size(26.dp)
            )
        } else {
            when (key.label) {
                &quot;?123&quot;, &quot;ABC&quot;, &quot;Space&quot; -&gt; AutoResizedText(
                    text = key.label,
                    color = textColor
                )

                else -&gt; Text(
                    text = key.label,
                    color = textColor,
                    fontSize = dimensionResource(id = R.dimen.key_textSize).value.sp
                )
            }

        }

        if (isPopupVisible.value &amp;&amp; key.shouldShowPopUp) {
            PopupScreen(
                label = key.label,
                offset = IntOffset(x = 0, y = -90)
            )
        }
    }
}


